    .filter(Trade::isSettled)
    .peek(t -> log.debug("After filter: {}", t.getTradeId()))  // debug observation
    .map(Trade::getSymbol)
    .peek(s -> log.debug("After map: {}", s))                   // debug observation
    .toList();

// ═══ BUG: peek for side effects — unreliable! ═══
List<String> collected = new ArrayList<>();
long count = trades.stream()
    .peek(t -> collected.add(t.getSymbol()))  // (Avoid) side effect in peek!
    .count();
// count() on a SIZED stream may return list.size() WITHOUT processing elements!
// peek() might NEVER execute! collected might be EMPTY!

// ═══ CORRECT alternative: forEach for side effects ═══
trades.stream().filter(Trade::isSettled).forEach(t -> auditService.log(t));
