@Test void peekMayBeSkippedByCountOptimization() {
    var counter = new java.util.concurrent.atomic.AtomicInteger(0);
    long count = List.of("A", "B", "C").stream()
        .peek(s -> counter.incrementAndGet())
        .count();
    // count() on a SIZED source may skip peek!
    // counter.get() might be 0 OR 3 — JVM-dependent!
    assertThat(count).isEqualTo(3);  // count is correct regardless
}
