package com.bank.java8;

import org.junit.jupiter.api.Test;
import java.util.ArrayList;
import java.util.List;
import static org.assertj.core.api.Assertions.assertThat;

class PeekTest {

    @Test
    void peekObservesElementsWhenTerminalPulls() {
        List<String> seen = new ArrayList<>();
        List<String> result = List.of("SAV2001", "CUR3001", "FD4001").stream()
            .filter(id -> !id.startsWith("FD"))
            .peek(seen::add)                 // debug observation only
            .map(String::toLowerCase)
            .toList();                        // terminal op pulls elements

        assertThat(result).containsExactly("sav2001", "cur3001");
        assertThat(seen).containsExactly("SAV2001", "CUR3001"); // peeked survivors
    }
}
